package com.yeyamo_mobile.api.notification_service.admin;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;
class AdminNotificationServiceTest {
 @Test void roleTargetCanBeReadWithoutChangingOtherAdmins(){var notifications=mock(AdminNotificationRepository.class);var reads=mock(AdminNotificationReadRepository.class);var entity=new AdminNotificationEntity();entity.id=UUID.randomUUID();entity.sourceEventId=UUID.randomUUID();entity.targetRole="SUPPORT";entity.type="SUPPORT";entity.title="Escalade";entity.message="Action requise";entity.resourceType="SUPPORT_CONVERSATION";entity.resourceId="c-1";entity.createdAt=Instant.now();when(notifications.findById(entity.id)).thenReturn(Optional.of(entity));when(reads.findByNotificationIdAndAdminId(entity.id,"admin-1")).thenReturn(Optional.empty());when(reads.save(any())).thenAnswer(i->i.getArgument(0));var service=new AdminNotificationService(notifications,reads);var response=service.read("admin-1",Set.of("SUPPORT"),entity.id);assertNotNull(response.readAt());verify(reads).save(argThat(r->"admin-1".equals(r.adminId)));verify(notifications,never()).save(any());}
 @Test void eventCreationIsIdempotent(){var notifications=mock(AdminNotificationRepository.class);var reads=mock(AdminNotificationReadRepository.class);UUID event=UUID.randomUUID();when(notifications.existsBySourceEventId(event)).thenReturn(true);new AdminNotificationService(notifications,reads).create(event,"SYSTEM","A","M","SYSTEM_ALERT","1",null,"SUPER_ADMIN");verify(notifications,never()).save(any());}
}
